def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track recent opponent behavior
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    opp_def = sum(1 for x in opp if x == 'D')

    # If opponent has never defected, keep cooperating
    if opp_def == 0:
        return 'C'

    # Count consecutive opponent defections at the end
    streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            streak += 1
        else:
            break

    # Count consecutive opponent cooperations before the current defection streak
    # Detect if we are in a retaliation spiral (alternating D/C)
    if n >= 3:
        alt = 0
        for i in range(n - 1, 0, -1):
            if opp[i] != opp[i - 1]:
                alt += 1
            else:
                break
        # If opponent has been alternating with us, break the spiral by cooperating
        if alt >= 3 and last_opp == 'D':
            return 'C'

    # Long defection streak: retaliate, but with a periodic olive branch
    if streak >= 4:
        # Every few rounds, offer cooperation to test if they'll reciprocate
        if streak % 3 == 0:
            return 'C'
        return 'D'

    # Short defection streak: tit-for-tat style punishment
    if last_opp == 'D':
        # If opponent has been mostly cooperative overall, forgive quickly
        if opp_def * 4 <= n:
            # Forgive with moderate probability to avoid long retaliation
            if rng.random() < 0.4:
                return 'C'
        return 'D'

    # Opponent cooperated last round. Cooperate to maintain mutual cooperation.
    # But if opponent has defected heavily overall, be defensive.
    if opp_def * 2 > n:
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    return 'C'
